// spec: .qa/e2e/specs/organizations-landing.md
// seed: tests/seed.company.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/company.json') });

test.describe('/organizations — «publish tender» CTAs by role', () => {
  test('Logged-in company: CTAs open the tender wizard (EN)', async ({ page }) => {
    // 1. Open /organizations, switch the language to English in the header
    await page.goto('/organizations');
    await page.getByRole('button', { name: 'שפה' }).click();
    await page.getByRole('button', { name: 'English', exact: true }).click();
    await expect(page).toHaveURL(/\/en\/organizations/);

    const ctas = page.locator('a[href="/en/publish/tender"]');
    await expect(ctas).toHaveCount(3);

    // 2. Click every tender-publish CTA (back to /en/organizations between clicks)
    for (let i = 0; i < 3; i++) {
      if (i > 0) {
        await page.goto('/en/organizations');
      }
      await ctas.nth(i).scrollIntoViewIfNeeded();
      await ctas.nth(i).click();

      // Expected: /en/publish/tender step 1, never /register
      await expect(page).toHaveURL(/\/en\/publish\/tender$/);
      await expect(page).not.toHaveURL(/\/register/);
      await expect(page.getByText('Step 1 of 4')).toBeVisible();
      await expect(page.getByRole('heading', { level: 1, name: 'Thank you for publishing a tender on Hunters!' })).toBeVisible();
      await expect(page.getByRole('radio')).toHaveCount(2);
      await expect(page.getByRole('button', { name: 'Continue' })).toBeVisible();
    }
  });
});
